import { Component, computed, signal } from '@angular/core';
import { VoteButton } from './vote-button';

@Component({
  selector: 'app-root',
  imports: [VoteButton],
  template: `
    <h1>Pick the class pet</h1>
    <!-- 3. Listen for (voted) on both buttons and call addVote($event) -->
    <app-vote-button label="Hamster" [votes]="tally().Hamster" />
    <app-vote-button label="Turtle" [votes]="tally().Turtle" />
    <p class="leader">Leader: {{ leader() }}</p>
  `,
})
export class App {
  tally = signal<Record<string, number>>({ Hamster: 0, Turtle: 0 });

  leader = computed(() => {
    const { Hamster = 0, Turtle = 0 } = this.tally();
    if (Hamster === Turtle) return 'Tie';
    return Hamster > Turtle ? 'Hamster' : 'Turtle';
  });

  addVote(choice: string) {
    this.tally.update((t) => ({ ...t, [choice]: (t[choice] ?? 0) + 1 }));
  }
}

