import { Injectable, computed, signal } from '@angular/core';
import { Quest } from './quest';

@Injectable({ providedIn: 'root' })
export class QuestService {
  private readonly list = signal<Quest[]>([]);
  private nextId = 1;

  readonly quests = this.list.asReadonly();

  // 3. remaining: a computed signal with how many quests are NOT done yet
  readonly remaining = computed(() => this.list().filter((q) => !q.done).length);

  add(title: string) {
    // 1. Trim the title. Ignore it if it's empty.
    //    Otherwise add { id: this.nextId++, title, done: false } to the end of the list.
    const clean = title.trim();
    if (!clean) return;
    this.list.update((all) => [...all, { id: this.nextId++, title: clean, done: false }]);
  }

  toggle(id: number) {
    // 2. Flip done for the quest with this id. Make a new array (map helps), don't change the old one.
    this.list.update((all) => all.map((q) => (q.id === id ? { ...q, done: !q.done } : q)));
  }
}

